import asyncio,json,os
from pathlib import Path
from playwright.async_api import async_playwright
async def main():
 f=json.loads(Path('/tmp/browser/billing/fixture.json').read_text())
 async with async_playwright() as p:
  b=await p.chromium.launch(headless=True);c=await b.new_context(viewport={'width':1280,'height':1800});page=await c.new_page();await page.goto('http://localhost:8080');await page.evaluate('([k,v])=>localStorage.setItem(k,v)',[os.environ['LOVABLE_BROWSER_SUPABASE_STORAGE_KEY'],os.environ['LOVABLE_BROWSER_SUPABASE_SESSION_JSON']]);await page.goto('http://localhost:8080')
  await page.goto('http://localhost:8080/projects/'+f['project']);await page.get_by_role('button',name='Project billing',exact=True).click();await page.locator('[data-billing-plan="ready"]').wait_for();await page.get_by_role('checkbox').nth(0).check();await page.get_by_role('checkbox').nth(1).check();await page.get_by_role('button',name='Merge planned invoices',exact=True).click();await page.get_by_role('textbox',name='Description',exact=True).fill('[QA DISPOSABLE] Combined study');await page.get_by_role('button',name='Save',exact=True).click();await page.get_by_text('[QA DISPOSABLE] Combined study',exact=True).wait_for();await page.screenshot(path='/tmp/browser/billing/merged.png');print('UI merge/readback passed')
  result=await page.evaluate('''async f=>{const {supabase:s}=await import('/src/integrations/supabase/client.ts');const call=async(n,a)=>{const r=await s.rpc(n,a);if(r.error)throw Error(n+': '+r.error.message);return r.data;};let plan=await call('pm_billing_plan',{_project:f.project});const group=plan.rows[0].manual_group_id;if(!group||plan.rows.some(r=>r.amount_value!==5000))throw Error('Merge totals');await call('pm_gantt_change_value',{_stage:f.stage,_expected:10000,_value:12000,_reason:'QA disposable increase',_responsibility:true});plan=await call('pm_billing_plan',{_project:f.project});if(plan.rows.some(r=>r.amount_value!==6000||r.manual_group_id!==group))throw Error('Gantt value/group preservation');await call('pm_billing_confirm',{_items:f.ids});await call('pm_billing_unmerge',{_group:group});plan=await call('pm_billing_plan',{_project:f.project});if(plan.rows.some(r=>r.manual_group_id||r.amount_value!==6000||r.workflow.confirmation_current))throw Error('Unmerge current values');await call('pm_billing_edit_description',{_item:f.ids[0],_revision:plan.rows.find(r=>r.id===f.ids[0]).revision,_description:'QA revised invoice text'});return {groupsUndone:true,amounts:plan.rows.map(r=>r.amount_value),descriptionSaved:true};}''',f);print(result)
  await page.reload();await page.get_by_role('button',name='Project billing',exact=True).click();await page.get_by_text('QA revised invoice text',exact=True).wait_for();await page.screenshot(path='/tmp/browser/billing/unmerged.png');print('Description survives reload');await b.close()
asyncio.run(main())
